  const { issues } = await sdk.sentry.listIssues({ project: "web" });
  const targets = issues.filter(i => i.status === "unresolved" && i.count >= 50);
  const existing: Record<string, unknown> = {};
  for (const t of targets) {
    const res = await sdk.linear.searchIssues({ query: `[Sentry] ${t.shortId}` });
    existing[t.shortId] = res.issues.map(i => ({ identifier: i.identifier, title: i.title }));
  }
  return { targets: targets.map(t => ({ shortId: t.shortId, count: t.count, culprit: t.culprit })), existing };
