{"code": "export async function main(input: {}) {
  const { issues } = await sdk.sentry.listIssues({ project: "web" });
  const targets = issues.filter(i => i.status === "unresolved" && i.count >= 50);
  const created = [];
  for (const t of targets) {
    const existing = await sdk.linear.searchIssues({ query: `[Sentry] ${t.shortId}` });
    if (existing.issues.some(i => i.title === `[Sentry] ${t.shortId}`)) continue;
    const res = await sdk.linear.createIssue({ title: `[Sentry] ${t.shortId}`, description: t.culprit });
    created.push({ shortId: t.shortId, title: `[Sentry] ${t.shortId}`, description: t.culprit, result: res });
  }
  return { planned: targets.map(t => t.shortId), created };
}", "input": {}}

